16	struct FJamPoseProxy : public FAnimInstanceProxy
17	{
18		explicit FJamPoseProxy(UAnimInstance* Instance)
19			: FAnimInstanceProxy(Instance)
20		{
21		}
22	
23		FJamPoseFrame Frame;
