25		virtual void PreUpdate(UAnimInstance* Instance, float DeltaSeconds) override
26		{
27			FAnimInstanceProxy::PreUpdate(Instance, DeltaSeconds);
28			Frame = CastChecked<UJamPoseInstance>(Instance)->Frame;
29		}
