31		virtual bool Evaluate(FPoseContext& Output) override
32		{
33			if (Frame.bRefPose || !Frame.Idle)
34			{
35				Output.ResetToRefPose();
36				return true;
37			}
38			Extract(*Frame.Idle, Frame.IdleTime, true, Output);
39			if (Frame.Move && Frame.MoveWeight > 0.f)
40			{
41				FPoseContext Move(Output);
42				Extract(*Frame.Move, Frame.MoveTime, true, Move);
43				FAnimationPoseData Base(Output);
44				FAnimationRuntime::BlendTwoPosesTogetherInPlace(Base, FAnimationPoseData(Move), 1.f - Frame.MoveWeight);
45			}
46			if (Frame.Fading && Frame.FadingWeight > 0.f)
47			{
48				FPoseContext Fading(Output);
49				Extract(*Frame.Fading, Frame.FadingTime, false, Fading);
50				BlendAction(Output, Fading, Frame.FadingWeight, Frame.bFadingFullBody);
51			}
52			if (Frame.Action && Frame.ActionWeight > 0.f)
53			{
54				FPoseContext Action(Output);
55				Extract(*Frame.Action, Frame.ActionTime, false, Action);
56				BlendAction(Output, Action, Frame.ActionWeight, Frame.bFullBody);
57			}
58			if (Frame.Lean && Frame.LeanWeight > 0.f)
59			{
60				AddLean(Output);
61			}
62			return true;
63		}
64	
65		/** Which bones are the upper body: UpperBodyBone and everything under it. Parents come first in a compact pose. */
66		static TArray<bool, TInlineAllocator<64>> UpperBody(const FPoseContext& Output)
67		{
68			const FBoneContainer& Bones = Output.Pose.GetBoneContainer();
69			const FReferenceSkeleton& RefSkeleton = Bones.GetReferenceSkeleton();
70			TArray<bool, TInlineAllocator<64>> Upper;
71			Upper.SetNumZeroed(Output.Pose.GetNumBones());
72			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
73			{
74				const FCompactPoseBoneIndex Parent = Output.Pose.GetParentBoneIndex(Bone);
75				const FName Name = RefSkeleton.GetBoneName(Bones.MakeMeshPoseIndex(Bone).GetInt());
76				Upper[Bone.GetInt()] = Name == UJamPoseInstance::UpperBodyBone || (Parent.IsValid() && Upper[Parent.GetInt()]);
77			}
78			return Upper;
79		}
80	
81		/** The hit lean: the upper body turns by the clip's peak against its first frame, an additive rotation only. */
82		void AddLean(FPoseContext& Output) const
83		{
84			FPoseContext Peak(Output);
85			Extract(*Frame.Lean, Frame.LeanTime, false, Peak);
86			FPoseContext Rest(Output);
87			Extract(*Frame.Lean, 0.f, false, Rest);
88			const TArray<bool, TInlineAllocator<64>> Upper = UpperBody(Output);
89			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
90			{
91				if (!Upper[Bone.GetInt()])
92				{
93					continue;
94				}
95				const FQuat Delta = Peak.Pose[Bone].GetRotation() * Rest.Pose[Bone].GetRotation().Inverse();
96				const FQuat Turn = FQuat::Slerp(FQuat::Identity, Delta, Frame.LeanWeight);
97				Output.Pose[Bone].SetRotation((Turn * Output.Pose[Bone].GetRotation()).GetNormalized());
98			}
