102		void BlendAction(FPoseContext& Output, const FPoseContext& Action, float Weight, bool bFullBody) const
103		{
104			const float Legs = bFullBody ? 1.f : 1.f - Frame.MoveWeight;
105			const TArray<bool, TInlineAllocator<64>> Upper = UpperBody(Output);
106			for (const FCompactPoseBoneIndex Bone : Output.Pose.ForEachBoneIndex())
107			{
108				Output.Pose[Bone].BlendWith(Action.Pose[Bone], Weight * (Upper[Bone.GetInt()] ? 1.f : Legs));
109			}
110		}
111	};
