117	constexpr float LeanRise = 0.05f;
118	constexpr float LeanLife = 0.35f;
119	// The hero's afterimages: how many, how far apart they are left, how long each fades, their neon.
120	constexpr int32 GhostCount = 4;
121	constexpr float GhostGap = 0.05f;
122	constexpr float GhostLife = 0.3f;
123	const FLinearColor GhostCyan(0.25f, 0.95f, 1.0f);
124	const FLinearColor GhostMagenta(1.0f, 0.25f, 0.75f);
125	const TCHAR* const GhostMaterial = TEXT("/Game/Characters/Materials/M_JamGhost.M_JamGhost");
126	// How fast the Publisher's body turns toward his facing, degrees per second (T-066).
127	constexpr float BossTurnRate = 540.f;
128	// How fast the walk fades in and out, per second.
129	constexpr float MoveBlendRate = 8.f;
130	
131	// The glow under the fighter: the first thing the hero loses.
132	constexpr float GlowIntensity = 6000.f;
133	constexpr float GlowRadiusInRadii = 12.f;
134	constexpr float GlowHeightInRadii = 2.f;
135	
136	// How a hit reads on the body: a short white flash.
137	constexpr float FlashSeconds = 0.09f;
138	
139	const FFigureInfo& FigureOf(EJamSide Side)
140	{
141		return Side == EJamSide::Hero ? HeroFigure : PublisherFigure;
142	}
