150	AJamFighterView::AJamFighterView()
151	{
152		PrimaryActorTick.bCanEverTick = false;
153		SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
154	
155		Body = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Body"));
156		Body->SetupAttachment(RootComponent);
157		JamShapes::Setup(*Body, JamShapes::Sphere());
158		Visor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Visor"));
159		Visor->SetupAttachment(RootComponent);
160		JamShapes::Setup(*Visor, JamShapes::Cube());
161	
162		ConstructRonin();
163	
164		Figure = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("Figure"));
165		Figure->SetupAttachment(RootComponent);
166		Figure->SetRelativeRotation(ModelYaw);
167		Figure->SetCollisionEnabled(ECollisionEnabled::NoCollision);
168		Figure->SetGenerateOverlapEvents(false);
169		Figure->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;
170	
171		Katana = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Katana"));
172		Katana->SetupAttachment(Figure, HandSocket);
173		Katana->SetCollisionEnabled(ECollisionEnabled::NoCollision);
174		Katana->SetGenerateOverlapEvents(false);
175		Katana->SetRelativeTransform(KatanaInHand);
176	
177		Trail = CreateDefaultSubobject<UNiagaraComponent>(TEXT("Trail"));
178		Trail->SetupAttachment(Katana);
179		// The blade's tip: the model's -X end, in the katana's own (unscaled) units.
180		Trail->SetRelativeLocation(FVector(-80.0, 0.0, 0.0));
181		Trail->SetAutoActivate(false);
182	
183		for (int32 Index = 0; Index < GhostCount; ++Index)
184		{
185			UPoseableMeshComponent* Ghost = CreateDefaultSubobject<UPoseableMeshComponent>(FName(TEXT("Ghost"), Index));
186			Ghost->SetupAttachment(RootComponent);
187			// A ghost stays where it was left while the hero moves on.
188			Ghost->SetUsingAbsoluteLocation(true);
189			Ghost->SetUsingAbsoluteRotation(true);
190			Ghost->SetUsingAbsoluteScale(true);
191			Ghost->SetCollisionEnabled(ECollisionEnabled::NoCollision);
192			Ghost->SetCastShadow(false);
193			Ghost->SetVisibility(false);
194			Ghosts.Add(Ghost);
195		}
196	
197		Glow = CreateDefaultSubobject<UPointLightComponent>(TEXT("Glow"));
198		Glow->SetupAttachment(RootComponent);
199		Glow->SetMobility(EComponentMobility::Movable);
200		Glow->SetCastShadows(false);
201		// The grid is found here, in a constructor: the layers switch to it at runtime.
202		JamShapes::Grid();
