205	void AJamFighterView::Init(EJamSide InSide, float Radius, float MaxSpeed, const FLinearColor& Color)
206	{
207		BodyRadius = Radius;
208		Side = InSide;
209		const float Height = Radius * HeightInRadii;
210		BaseColor = Color;
211		Speed = FMath::Max(1.f, MaxSpeed);
212		const float R = Radius / JamShapes::UnitSize;
213		Body->SetRelativeScale3D(FVector(2.f * Radius, 2.f * Radius, Height) / JamShapes::UnitSize);
214		Body->SetRelativeLocation(FVector(0.0, 0.0, 0.5 * Height));
215		Visor->SetRelativeScale3D(VisorSizeInRadii * R);
216		Visor->SetRelativeLocation(FVector(Radius * VisorForwardInRadii, 0.0, Height * VisorHeightAt));
217	
218		InitRonin(Radius);
219	
220		const FFigureInfo& Info = FigureOf(Side);
221		Figure->SetSkeletalMesh(LoadObject<USkeletalMesh>(nullptr, Info.Mesh));
222		Figure->SetAnimInstanceClass(UJamPoseInstance::StaticClass());
223		Clips.SetNum(UE_ARRAY_COUNT(Info.Clips));
224		for (int32 Index = 0; Index < Clips.Num(); ++Index)
225		{
226			Clips[Index] = Info.Clips[Index].Asset ? LoadObject<UAnimSequence>(nullptr, Info.Clips[Index].Asset) : nullptr;
227		}
228		Skin = UMaterialInstanceDynamic::Create(LoadObject<UMaterialInterface>(nullptr, Info.Material), this);
229		if (Skin)
230		{
231			Skin->GetScalarParameterValue(TEXT("NeonGlow"), NeonGlow);
232		}
233		GhostBornAt.Init(-UE_BIG_NUMBER, Ghosts.Num());
234		if (Side == EJamSide::Hero)
235		{
236			InitHeroGear();
237		}
238	
239		Glow->SetRelativeLocation(FVector(0.0, 0.0, GlowHeightInRadii * Radius));
240		Glow->SetIntensity(GlowIntensity);
241		Glow->SetAttenuationRadius(GlowRadiusInRadii * Radius);
242		Glow->SetLightColor(Color);
243	
244		// Forces the first SetLayers to apply everything.
245		Shown.bModel = !Shown.bModel;
246		SetLayers(FJamLayers());
247	}
