249	void AJamFighterView::InitHeroGear()
250	{
251		if (UNiagaraSystem* Ribbon = LoadObject<UNiagaraSystem>(nullptr, TrailSystem))
252		{
253			Trail->SetAsset(Ribbon);
254			Trail->SetVariableLinearColor(TEXT("User.Color"), FLinearColor(0.3f, 0.95f, 1.0f));
255		}
256		Katana->SetStaticMesh(LoadObject<UStaticMesh>(nullptr, KatanaMesh));
257	#if !UE_BUILD_SHIPPING
258		// -JamKatana=X,Y,Z,Pitch,Yaw,Roll: the blade's place in the hand, tried out without a build (the pose gallery).
259		FString Grip;
260		TArray<FString> Parts;
261		if (FParse::Value(FCommandLine::Get(), TEXT("JamKatana="), Grip, false) && Grip.ParseIntoArray(Parts, TEXT(",")) == 6)
262		{
263			Katana->SetRelativeLocationAndRotation(FVector(FCString::Atod(*Parts[0]), FCString::Atod(*Parts[1]), FCString::Atod(*Parts[2])),
264				FRotator(FCString::Atod(*Parts[3]), FCString::Atod(*Parts[4]), FCString::Atod(*Parts[5])));
265		}
266	#endif
267		UMaterialInterface* GhostLook = LoadObject<UMaterialInterface>(nullptr, GhostMaterial);
268		for (int32 Index = 0; Index < Ghosts.Num(); ++Index)
269		{
270			Ghosts[Index]->SetSkinnedAssetAndUpdate(Figure->GetSkinnedAsset());
271			UMaterialInstanceDynamic* GhostSkin = UMaterialInstanceDynamic::Create(GhostLook, this);
272			GhostSkin->SetVectorParameterValue(TEXT("Color"), Index % 2 == 0 ? GhostCyan : GhostMagenta);
273			Ghosts[Index]->SetMaterial(0, GhostSkin);
274			GhostSkins.Add(GhostSkin);
275		}
