278	void AJamFighterView::SetLayers(const FJamLayers& InLayers)
279	{
280		if (InLayers == Shown)
281		{
282			return;
283		}
284		Shown = InLayers;
285		// Three looks of the hero (T-067): the 3D art, the shape ronin of before the models, the bean.
286		Figure->SetVisibility(Shown.bModel && Shown.bArt, true);
287		Ronin->SetVisibility(Shown.bModel && !Shown.bArt, true);
288		Body->SetVisibility(!Shown.bModel);
289		Visor->SetVisibility(!Shown.bModel);
290		Glow->SetVisibility(Shown.bEffects);
291		if (Skin)
292		{
