298	void AJamFighterView::Repaint()
299	{
300		const bool bGrid = !Shown.bMaterials && !bFlashing;
301		const FLinearColor Flashed = bFlashing ? FMath::Lerp(BaseColor, FLinearColor::White, FlashWeight) : BaseColor;
302		if (!Shown.bModel)
303		{
304			JamShapes::Look(*Body, Flashed, bGrid);
305			JamShapes::Look(*Visor, VisorColor, bGrid);
306			return;
307		}
308		if (!Shown.bArt)
309		{
310			PaintRonin(bGrid);
311			return;
312		}
313		UMaterialInterface* Grid = JamShapes::Grid();
314		Figure->SetMaterial(0, bGrid ? Grid : Skin.Get());
315		if (Katana->GetStaticMesh())
316		{
317			Katana->SetMaterial(0, bGrid ? Grid : Katana->GetStaticMesh()->GetMaterial(0));
318		}
319		if (Skin)
320		{
321			Skin->SetScalarParameterValue(TEXT("Flash"), bFlashing ? FlashWeight : 0.f);
322		}
323	}
