325	void AJamFighterView::Flash(float Time, float Weight)
326	{
327		// A light hit inside the flash of a heavy one does not dim it.
328		const bool bStillFlashing = Time < FlashUntil;
329		const float Next = bStillFlashing ? FMath::Max(FlashWeight, Weight) : Weight;
330		FlashUntil = Time + FlashSeconds;
331		if (Next != FlashWeight)
332		{
333			FlashWeight = Next;
334			// Sync repaints only when the flash starts or ends: a new weight inside one is painted here.
335			if (bFlashing)
336			{
337				Repaint();
338			}
339		}
340	}
