342	void AJamFighterView::Start(EJamClip Clip, float Lead, bool bFullBody, float Time)
343	{
344		const UAnimSequence* Sequence = Clips.IsValidIndex(static_cast<int32>(Clip)) ? Clips[static_cast<int32>(Clip)].Get() : nullptr;
345		if (!Sequence)
346		{
347			return;
348		}
349		const FClipInfo& Info = InfoOf(Side, Clip);
350		// The action cut short fades out under the new one (T-066): a chain of strikes flows instead of popping.
351		if (Action.Clip != EJamClip::None)
352		{
353			FadingWeight = WeightOf(Action, Time);
354			FadingAt = Time;
355			Fading = Action;
356		}
357		Action.Clip = Clip;
358		Action.StartedAt = Time;
359		Action.bFullBody = bFullBody;
360		Action.bHold = Clip == EJamClip::Death;
361		Action.End = Info.End > 0.f ? Info.End : Sequence->GetPlayLength();
362		// A held clip and the show-off play whole at their own speed: nothing in the fight lands with them.
363		const bool bWhole = Action.bHold || Clip == EJamClip::Entrance;
364		// A throw has left the hand already: it shows from the release on, so the shot is drawn leaving that hand.
365		const float MinLead = Clip == EJamClip::Throw ? 0.f : ShortestLead;
366		Action.Playback = bWhole ? FJamPlayback() : JamPoseRules::Fit(Info.Impact, FMath::Max(Lead, MinLead), MinClipRate, MaxClipRate);
367	}
