369	void AJamFighterView::HoldPose(EJamClip Clip, float ClipTime, float Time)
370	{
371		Start(Clip, 0.f, true, Time);
372		Action.bHold = true;
373		Action.End = UE_BIG_NUMBER;
374		Action.Playback.From = ClipTime;
375		Action.Playback.Rate = 0.f;
376	}
