408	void AJamFighterView::Interrupt(float Time)
409	{
410		if (Action.Clip == EJamClip::None || Action.bHold)
411		{
412			return;
413		}
414		// The clip ends one fade from now, wherever it is.
415		const float Age = Time - Action.StartedAt;
416		Action.End = FMath::Min(Action.End, Action.Playback.From + (Age + BlendSeconds) * Action.Playback.Rate);
417	}
