419	void AJamFighterView::Act(const FJamFight& Fight, TConstArrayView<FJamEvent> Events, float Time)
420	{
421		if (JamPoseRules::IsDown(Fight, Side))
422		{
423			if (Action.Clip != EJamClip::Death)
424			{
425				Start(EJamClip::Death, 0.f, true, Time);
426			}
427			return;
428		}
429		if (Action.Clip == EJamClip::Death)
430		{
431			// The fight started again: he is up at once.
432			Action = FAction();
433		}
434		if (JamPoseRules::Shakes(Fight, Side, Events, StaggerHit))
435		{
436			HitAt = Time;
437			GhostAt = Time;
438			GhostsLeft = 0;
439			UE_LOG(LogJamGame, Verbose, TEXT("%s shaken by a hit at %.2f s"), Side == EJamSide::Hero ? TEXT("Hero") : TEXT("Publisher"), Time);
440		}
441		// A dash of the hero's leaves its afterimages too (T-066): the Sandevistan trail of the hit, without the lean.
442		if (Events.ContainsByPredicate([this](const FJamEvent& E) { return E.Type == EJamEvent::Dash && E.Side == Side; }))
443		{
444			GhostAt = Time;
445			GhostsLeft = 0;
446		}
447		const FJamCue Cue = JamPoseRules::CueFor(Fight, Side, Events);
448		if (Cue.Clip != EJamClip::None && JamPoseRules::Replaces(Cue.Clip, Action.Clip))
449		{
450			Start(Cue.Clip, Cue.Lead, Cue.bFullBody, Time);
451		}
452	}
453	
454	float AJamFighterView::ClipTimeOf(const FAction& Of, float Time) const
455	{
456		return FMath::Min(Of.Playback.From + (Time - Of.StartedAt) * Of.Playback.Rate, Of.End);
457	}
458	
459	float AJamFighterView::WeightOf(const FAction& Of, float Time) const
460	{
461		const float Age = Time - Of.StartedAt;
462		const float Remaining = Of.bHold || Of.Playback.Rate <= 0.f ? UE_BIG_NUMBER : (Of.End - Of.Playback.From) / Of.Playback.Rate - Age;
463		return JamPoseRules::Weight(Age, Remaining, BlendSeconds);
464	}
465	
466	void AJamFighterView::ShowFading(FJamPoseFrame& Out, float Time)
467	{
468		const float FadeLeft = Fading.Clip == EJamClip::None ? 0.f : FadingWeight * (1.f - (Time - FadingAt) / BlendSeconds);
469		if (FadeLeft <= 0.f)
470		{
471			Fading = FAction();
472		}
473		Out.Fading = FadeLeft > 0.f ? Clips[static_cast<int32>(Fading.Clip)].Get() : nullptr;
474		Out.FadingTime = FadeLeft > 0.f ? ClipTimeOf(Fading, Time) : 0.f;
475		Out.FadingWeight = FMath::Max(0.f, FadeLeft);
476		Out.bFadingFullBody = Fading.bFullBody;
477	}
478	
479	void AJamFighterView::Animate(float Moving, float Stride, float Time)
480	{
481		const float Dt = FMath::Clamp(Time - LastTime, 0.f, 0.1f);
482		LastTime = Time;
483		UJamPoseInstance* Pose = Cast<UJamPoseInstance>(Figure->GetAnimInstance());
484		if (!Pose)
485		{
486			return;
487		}
488		FJamPoseFrame& Out = Pose->Frame;
489		Out.bRefPose = !Shown.bAnimation;
490		const FFigureInfo& Info = FigureOf(Side);
491		MoveWeight = FMath::FInterpConstantTo(MoveWeight, Moving, Dt, MoveBlendRate);
492		MoveTime += Dt * Stride * FMath::Clamp(Moving * Speed / Info.MoveSpeed, 0.f, Info.MaxMoveRate);
493		if (const UAnimSequence* MoveClip = Clips[static_cast<int32>(EJamClip::Move)])
494		{
495			// Backpedalling runs the clock backwards: kept inside the clip so the loop never sees a negative time.
496			MoveTime = FMath::Fmod(MoveTime, MoveClip->GetPlayLength());
497			MoveTime += MoveTime < 0.f ? MoveClip->GetPlayLength() : 0.f;
498		}
499		Out.Idle = Clips[static_cast<int32>(EJamClip::Idle)];
500		Out.IdleTime = Time;
501		Out.Move = Clips[static_cast<int32>(EJamClip::Move)];
502		Out.MoveTime = MoveTime;
503		Out.MoveWeight = MoveWeight;
504		Out.Lean = Clips[static_cast<int32>(EJamClip::Hit)];
505		Out.LeanTime = InfoOf(Side, EJamClip::Hit).Impact;
506		Out.LeanWeight = HitAt < 0.f ? 0.f : JamPoseRules::LeanWeight(Time - HitAt, LeanRise, LeanLife);
507	
508		ShowFading(Out, Time);
509	
510		Out.Action = nullptr;
511		Out.ActionWeight = 0.f;
512		if (Action.Clip == EJamClip::None)
513		{
514			return;
515		}
516		const float Age = Time - Action.StartedAt;
517		const float ClipTime = ClipTimeOf(Action, Time);
518		const float Weight = WeightOf(Action, Time);
519		if (Weight <= 0.f && Age > BlendSeconds)
520		{
521			Action = FAction();
522			return;
523		}
524		// The blade leaves its ribbon while it swings, in the full art only (T-069).
525		const bool bSwinging = Action.Clip == EJamClip::StrikeA || Action.Clip == EJamClip::StrikeB || Action.Clip == EJamClip::Heavy;
526		SetTrail(Shown.bArt && bSwinging && Weight > 0.2f);
527		Out.Action = Clips[static_cast<int32>(Action.Clip)];
528		Out.ActionTime = ClipTime;
529		Out.ActionWeight = Weight;
530		Out.bFullBody = Action.bFullBody;
531	}
532	
533	void AJamFighterView::SetTrail(bool bOn)
534	{
535		if (bOn != bTrailOn && Trail->GetAsset())
536		{
537			bTrailOn = bOn;
538			bOn ? Trail->Activate(true) : Trail->Deactivate();
539		}
540	}
541	
542	void AJamFighterView::Face(const FVector2D& Dir)
543	{
544		SetActorRotation(FRotator(0.0, FMath::RadiansToDegrees(FMath::Atan2(Dir.Y, Dir.X)), 0.0));
545	}
546	
547	void AJamFighterView::Sync(const FJamFighter& Fighter, float Alpha, float Time)
548	{
549		const float Dt = FMath::Clamp(Time - LastSyncTime, 0.f, 0.1f);
550		LastSyncTime = Time;
551		const FVector2D Pos = FMath::Lerp(Fighter.PrevPos, Fighter.Pos, static_cast<double>(Alpha));
552		const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Fighter.Facing.Y, Fighter.Facing.X));
553		// The hero turns at once to the cursor (Face); the Publisher's heavy body turns at a rate instead of snapping (T-066).
554		const double ShownYaw = Side == EJamSide::Boss ? FMath::FixedTurn(GetActorRotation().Yaw, Yaw, BossTurnRate * Dt) : Yaw;
555		SetActorLocationAndRotation(FVector(Pos.X, Pos.Y, 0.0), FRotator(0.0, ShownYaw, 0.0));
556		const FVector2D Step = Fighter.Pos - Fighter.PrevPos;
557		const float StepSpeed = Step.Size() * JamSim::StepsPerSecond;
558		const float Moving = FMath::Clamp(StepSpeed / Speed, 0.f, 1.f);
559		Animate(Moving, JamPoseRules::StrideSign(Step, Fighter.Facing), Time);
560		if (Shown.bModel && !Shown.bArt)
561		{
562			AnimateRonin(Moving, Time);
563		}
564		UpdateGhosts(Time);
565		const bool bFlashNow = Time < FlashUntil;
566		if (bFlashNow != bFlashing)
567		{
568			bFlashing = bFlashNow;
569			Repaint();
570		}
571	}
572	
573	void AJamFighterView::UpdateGhosts(float Time)
574	{
575		if (GhostSkins.IsEmpty())
576		{
577			return;
578		}
579		// The afterimages are an effect of a moving body: gone with the effects, the animation or the model.
580		const bool bShow = Shown.bArt && Shown.bEffects && Shown.bAnimation && Shown.bModel;
581		const int32 Due = bShow && GhostAt >= 0.f ? JamPoseRules::GhostsBy(Time - GhostAt, Ghosts.Num(), GhostGap) : 0;
582		for (; GhostsLeft < Due; ++GhostsLeft)
583		{
584			UPoseableMeshComponent& Ghost = *Ghosts[GhostsLeft];
585			Ghost.SetWorldTransform(Figure->GetComponentTransform());
586			Ghost.CopyPoseFromSkeletalComponent(Figure);
587			GhostBornAt[GhostsLeft] = Time;
588		}
589		for (int32 Index = 0; Index < Ghosts.Num(); ++Index)
590		{
591			const float Alpha = bShow ? JamPoseRules::GhostAlpha(Time - GhostBornAt[Index], GhostLife) : 0.f;
592			Ghosts[Index]->SetVisibility(Alpha > 0.f);
593			GhostSkins[Index]->SetScalarParameterValue(TEXT("Fade"), Alpha);
594		}
595	}
