void AJamFighterView::Animate(float Moving, float Stride, float Time)
{
	const float Dt = FMath::Clamp(Time - LastTime, 0.f, 0.1f);
	LastTime = Time;
	UJamPoseInstance* Pose = Cast<UJamPoseInstance>(Figure->GetAnimInstance());
	if (!Pose)
	{
		return;
	}
	FJamPoseFrame& Out = Pose->Frame;
	Out.bRefPose = !Shown.bAnimation;
	const FFigureInfo& Info = FigureOf(Side);
	MoveWeight = FMath::FInterpConstantTo(MoveWeight, Moving, Dt, MoveBlendRate);
	MoveTime += Dt * Stride * FMath::Clamp(Moving * Speed / Info.MoveSpeed, 0.f, Info.MaxMoveRate);
	if (const UAnimSequence* MoveClip = Clips[static_cast<int32>(EJamClip::Move)])
	{
		// Backpedalling runs the clock backwards: kept inside the clip so the loop never sees a negative time.
		MoveTime = FMath::Fmod(MoveTime, MoveClip->GetPlayLength());
		MoveTime += MoveTime < 0.f ? MoveClip->GetPlayLength() : 0.f;
	}
	Out.Idle = Clips[static_cast<int32>(EJamClip::Idle)];
	Out.IdleTime = Time;
	Out.Move = Clips[static_cast<int32>(EJamClip::Move)];
	Out.MoveTime = MoveTime;
	Out.MoveWeight = MoveWeight;
	Out.Lean = Clips[static_cast<int32>(EJamClip::Hit)];

