67		void BlendRuns(FPoseContext& Output) const
68		{
69			FPoseContext Walk(Output);
70			float Taken = 0.f;
71			for (int32 Run = 0; Run < FJamPoseFrame::RunCount; ++Run)
72			{
73				const float Weight = Frame.RunWeights[Run];
74				if (!Frame.Runs[Run] || Weight <= 0.f)
