80					Extract(*Frame.Runs[Run], Frame.RunTimes[Run], true, Walk);
81				}
82				else
83				{
84					FPoseContext Next(Output);
85					Extract(*Frame.Runs[Run], Frame.RunTimes[Run], true, Next);
86					FAnimationPoseData Into(Walk);
87					FAnimationRuntime::BlendTwoPosesTogetherInPlace(Into, FAnimationPoseData(Next), Taken / (Taken + Weight));
