	const int32 Index""", """	const float Age = Time - StrideGalleryStart;
	if (Age >= EachSeconds * UE_ARRAY_COUNT(Angles))
	{
		const float CircleDt = FMath::Clamp(Time - StrideGalleryTime, 0.f, 0.1f);
