"""Moves the fighter's motion (Sync, Face, AnimateStride, DescribeStride) out of JamFighterView.cpp into
JamFighterMotion.cpp; the figure table's run speeds reach it through members filled in Init."""
import re

root = "F:/Unreal_Engine/UnrealProjects/MegaJam2026_C/Source/JamGame/"
view = root + "Private/View/JamFighterView.cpp"
s = open(view, encoding="utf-8").read()


def cut(start, end):
    """Removes and returns s[start marker : end marker)."""
    global s
    a = s.index(start)
    b = s.index(end, a)
    block = s[a:b]
    s = s[:a] + s[b:]
    return block


describe = cut("FString AJamFighterView::DescribeStride() const", "FVector AJamFighterView::ThrowingHand() const")
stride = cut("void AJamFighterView::AnimateStride(", "void AJamFighterView::Animate(")
face_sync = cut("void AJamFighterView::Face(const FVector2D& Dir)", "void AJamFighterView::UpdateGhosts(float Time)")
consts = cut("// How fast the Publisher's body turns toward his facing, degrees per second (T-066).", "// How fast the walk fades in and out, per second.")
stride_consts = cut("// T-078: the hips turn toward the move at most this far", "// The lean into a turn:")
angle_const = cut("// Below this speed the move angle stays as it was", "\n// The glow under the fighter")

# The figure's run speeds become members, so the motion file needs no figure table.
stride = stride.replace("""	const FFigureInfo& Info = FigureOf(Side);
	const bool bDiagonals""", """	const bool bDiagonals""")
stride = stride.replace("""	float RunSpeeds[FJamPoseFrame::RunCount] = { Info.MoveSpeed, 1.f, 1.f, 1.f, 1.f, Info.MoveSpeed };
	for (int32 Index = 0; Index < Diagonals.Num(); ++Index)
	{
		Runs[1 + Index] = Diagonals[Index];
		RunSpeeds[1 + Index] = Info.Diagonals[Index].Speed;
	}""", """	for (int32 Index = 0; Index < Diagonals.Num(); ++Index)
	{
		Runs[1 + Index] = Diagonals[Index];
	}""")
stride = stride.replace("JamPoseRules::StrideRate(GroundSpeed, RunSpeeds[Run], Info.MaxMoveRate)", "JamPoseRules::StrideRate(GroundSpeed, RunSpeeds[Run], MaxRunRate)")
assert "Info." not in stride, stride

old_init = """	StrideWeights.Init(0.f, static_cast<int32>(EJamStride::Num));"""
assert s.count(old_init) == 1
s = s.replace(old_init, """	MaxRunRate = Info.MaxMoveRate;
	RunSpeeds.Init(Info.MoveSpeed, static_cast<int32>(EJamStride::Num));
	for (int32 Index = 0; Index < Diagonals.Num(); ++Index)
	{
